:{"background":"color-mix(in srgb, var(--wp--preset--color--contrast) 85%, transparent)","text":"var(--wp--preset--color--base)"}},"spacing":{"padding":{"bottom":"0.6rem","left":"1.6rem","right":"1.6rem","top":"0.6rem"}}}},"css":"/* ===== サイドバーのカレンダーだけに適用 ===== */
.my-sidebar-calendar table {
 width: 100%;
 border-collapse: collapse;
 background: transparent !important;
}

.my-sidebar-calendar caption {
 caption-side: top;
 text-align: left;
 font-size: 0.95em;
 font-weight: 600;
 color: #ffffff !important;
 background: none !important;
 padding-bottom: 0.8em;
}

.my-sidebar-calendar thead th {
 border: none !important;
 background: none !important;
 font-weight: 400;
 font-size: 0.8em;
 color: #888888 !important;
 padding: 0.4em 0;
}

.my-sidebar-calendar tbody td {
 border: none !important;
 background: none !important;
 text-align: center;
 font-size: 0.85em;
 color: #999999 !important;
 padding: 0.5em 0;
}

.my-sidebar-calendar tbody td a {
 color: #ffffff !important;
 text-decoration: none !important;
}
.my-sidebar-calendar tbody td a:hover {
 text-decoration: underline !important;
}

.my-sidebar-calendar tbody #today {
 color: #ffffff !important;
 font-weight: 700;
}

.my-sidebar-calendar .wp-calendar-nav {
 padding-top: 0.6em;
 font-size: 0.8em;
 color: #888888 !important;
}
.my-sidebar-calendar .wp-calendar-nav a {
 color: #cccccc !important;
 text-decoration: none !important;
}
.my-sidebar-calendar .wp-calendar-nav a:hover {
 text-decoration: underline !important;
}

/* ===== セル幅・余白の調整(修正版) ===== */
.my-sidebar-calendar table {
 width: auto;
 margin: 0 auto 0 0; /* 左寄せ */
}

.my-sidebar-calendar thead th,
.my-sidebar-calendar tbody td {
 width: 2em;
 padding: 0.35em 0.2em !important;
}

.my-sidebar-calendar thead th {
 letter-spacing: 0.02em;
}

.my-sidebar-calendar tbody td {
 line-height: 1.6;
}"},"settings":{"color":{"palette":{"theme":[{"color":"#1B1B1B","name":"ベース","slug":"base"},{"color":"#F0F0F0","name":"コントラスト","slug":"contrast"},{"color":"#786D0A","name":"アクセント1","slug":"accent-1"},{"color":"#442369","name":"アクセント2","slug":"accent-2"},{"color":"#D1D0EA","name":"アクセント3","slug":"accent-3"},{"color":"#CBCBCB","name":"アクセント4","slug":"accent-4"},{"color":"#353535","name":"アクセント5","slug":"accent-5"},{"color":"#FFFFFF33","name":"アクセント6","slug":"accent-6"}]}},"blocks":{"core/image":{"appearanceTools":false,"useRootPaddingAwareAlignments":true,"background":{"backgroundImage":true,"backgroundSize":true},"border":{"color":true,"radius":true,"style":true,"width":true},"shadow":{"presets":{"default":[{"name":"Natural","slug":"natural","shadow":"6px 6px 9px rgba(0, 0, 0, 0.2)"},{"name":"Deep","slug":"deep","shadow":"12px 12px 50px rgba(0, 0, 0, 0.4)"},{"name":"Sharp","slug":"sharp","shadow":"6px 6px 0px rgba(0, 0, 0, 0.2)"},{"name":"Outlined","slug":"outlined","shadow":"6px 6px 0px -3px rgb(255, 255, 255), 6px 6px rgb(0, 0, 0)"},{"name":"Crisp","slug":"crisp","shadow":"6px 6px 0px rgb(0, 0, 0)"}]},"defaultPresets":true},"color":{"background":true,"button":true,"caption":true,"custom":true,"customDuotone":true,"customGradient":true,"defaultDuotone":false,"defaultGradients":false,"defaultPalette":false,"duotone":{"default":[{"name":"ダークグレースケール","colors":["#000000","#7f7f7f"],"slug":"dark-grayscale"},{"name":"グレースケール","colors":["#000000","#ffffff"],"slug":"grayscale"},{"name":"紫と黄色","colors":["#8c00b7","#fcff41"],"slug":"purple-yellow"},{"name":"青と赤","colors":["#000097","#ff4747"],"slug":"blue-red"},{"name":"ミッドナイト","colors":["#000000","#00a5ff"],"slug":"midnight"},{"name":"マゼンタと黄色","colors":["#c7005a","#fff278"],"slug":"magenta-yellow"},{"name":"紫と緑","colors":["#a60072","#67ff66"],"slug":"purple-green"},{"name":"青とオレンジ","colors":["#1900d8","#ffa96b"],"slug":"blue-orange"}]},"gradients":{"default":[{"name":"鮮やかなシアンブルーから鮮やかな紫","gradient":"linear-gradient(135deg,rgb(6,147,227) 0%,rgb(155,81,224) 100%)","slug":"vivid-cyan-blue-to-vivid-purple"},{"name":"明るいグリーンシアンから鮮やかなグリーンシアン","gradient":"linear-gradient(135deg,rgb(122,220,180) 0%,rgb(0,208,130) 100%)","slug":"light-green-cyan-to-vivid-green-cyan"},{"name":"明るく鮮やかな琥珀色から明るく鮮やかなオレンジ色","gradient":"linear-gradient(135deg,rgb(252,185,0) 0%,rgb(255,105,0) 100%)","slug":"luminous-vivid-amber-to-luminous-vivid-orange"},{"name":"明るく鮮やかなオレンジ色から鮮やかな赤","gradient":"linear-gradient(135deg,rgb(255,105,0) 0%,rgb(207,46,46) 100%)","slug":"luminous-vivid-orange-to-vivid-red"},{"name":"非常に薄いグレーからシアンブルー系グレー","gradient":"linear-gradient(135deg,rgb(238,238,238) 0%,rgb(169,184,195) 100%)","slug":"very-light-gray-to-cyan-bluish-gray"},{"name":"寒色から暖色へのスペクトラム","gradient":"linear-gradient(135deg,rgb(74,234,220) 0%,rgb(151,120,209) 20%,rgb(207,42,186) 40%,rgb(238,44,130) 60%,rgb(251,105,98) 80%,rgb(254,248,76) 100%)","slug":"cool-to-warm-spectrum"},{"name":"赤みのある明るい紫","gradient":"linear-gradient(135deg,rgb(255,206,236) 0%,rgb(152,150,240) 100%)","slug":"blush-light-purple"},{"name":"赤みのあるボルドー","gradient":"linear-gradient(135deg,rgb(254,205,165) 0%,rgb(254,45,45) 50%,rgb(107,0,62) 100%)","slug":"blush-bordeaux"},{"name":"明るい夕暮れ","gradient":"linear-gradient(135deg,rgb(255,203,112) 0%,rgb(199,81,192) 50%,rgb(65,88,208) 100%)","slug":"luminous-dusk"},{"name":"淡い海","gradient":"linear-gradient(135deg,rgb(255,245,203) 0%,rgb(182,227,212) 50%,rgb(51,167,181) 100%)","slug":"pale-ocean"},{"name":"エレクトリックグラス","gradient":"linear-gradient(135deg,rgb(202,248,128) 0%,rgb(113,206,126) 100%)","slug":"electric-grass"},{"name":"ミッドナイト","gradient":"linear-gradient(135deg,rgb(2,3,129) 0%,rgb(40,116,252) 100%)","slug":"midnight"}]},"heading":true,"link":true,"palette":{"default":[{"name":"黒","slug":"black","color":"#000000"},{"name":"シアンブルーグレー","slug":"cyan-bluish-gray","color":"#abb8c3"},{"name":"白","slug":"white","color":"#ffffff"},{"name":"淡いピンク","slug":"pale-pink","color":"#f78da7"},{"name":"鮮やかな赤","slug":"vivid-red","co